node -e "
const re = /[\p{L}\p{N}_]+(?:\.?[\p{L}\p{N}_]+)*/gu;
const bare = /\w+(?:\.?\w+)*/g;
const s = 'héllo 世界 www.example.com 1.5 a_b';
console.log('unicode-aware:', JSON.stringify(s.match(re)));
console.log('bare \\\\w    :', JSON.stringify(s.match(bare)));
console.log('bare under u:', JSON.stringify(s.match(/\w+/gu)));
// decomposed NFD check
const nfd = 'héllo';
console.log('NFD via [\\\\p{L}\\\\p{N}_]:', JSON.stringify(nfd.match(re)));
console.log('NFD via +marks       :', JSON.stringify(nfd.match(/[\p{L}\p{N}\p{M}_]+/gu)));
" 2>&1
